export const c11Phy8HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.7; font-size: 16px;\">\n\n  <!-- QUICK GLOSSARY & BASIC DEFINITIONS -->\n  <div style=\"background: rgba(255, 81, 47, 0.05); border: 1.5px solid #FF512F; border-radius: 12px; padding: 16px; margin-bottom: 25px;\">\n    <h2 class=\"text-center\" style=\"color: #FF512F; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">📖 Quick Glossary & Basic Definitions</h2>\n    <p class=\"text-center\" style=\"color: #FF512F; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Key Fundamental Terms & Concepts for Unit VIII: Thermodynamics</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 10px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>1. Thermal Equilibrium:</b>\n        <span style=\"color: #FFFFFF;\">State in which two interacting systems have equal temperature, so net heat transfer between them is zero.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>2. Zeroth Law of Thermodynamics:</b>\n        <span style=\"color: #FFFFFF;\">If A and B are separately in thermal equilibrium with C, then A and B are in thermal equilibrium with each other.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>3. Internal Energy (U):</b>\n        <span style=\"color: #FFFFFF;\">The total molecular kinetic and potential energy of a thermodynamic system. State function dependent only on T for ideal gas.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>4. First Law of Thermodynamics:</b>\n        <span style=\"color: #FFFFFF;\">Conservation of energy statement: Heat added ΔQ equals internal energy change ΔU plus work done ΔW (ΔQ = ΔU + ΔW).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>5. Isothermal Process:</b>\n        <span style=\"color: #FFFFFF;\">A slow thermodynamic process occurring at constant temperature (ΔT = 0, ΔU = 0, P V = Const).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>6. Adiabatic Process:</b>\n        <span style=\"color: #FFFFFF;\">A sudden thermodynamic process with no heat exchange with surroundings (Q = 0, P V<sup>γ</sup> = Const).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>7. Cyclic Process:</b>\n        <span style=\"color: #FFFFFF;\">A sequence of processes returning system to initial state (ΔU_cycle = 0, Q_net = W_net = Area of P-V loop).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>8. Second Law (Kelvin-Planck):</b>\n        <span style=\"color: #FFFFFF;\">Impossible to construct a heat engine converting heat absorbed completely into work without rejecting heat to cold sink.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>9. Second Law (Clausius):</b>\n        <span style=\"color: #FFFFFF;\">Impossible for heat to flow spontaneously from a colder body to a hotter body without external work input.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>10. Carnot Engine Efficiency (η):</b>\n        <span style=\"color: #FFFFFF;\">Maximum theoretical efficiency of reversible engine operating between T₁ and T₂: η = 1 - T₂ / T₁.</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION 1: THERMAL EQUILIBRIUM AND ZEROTH LAW OF THERMODYNAMICS (100% OFFICIAL SYLLABUS TITLE) -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 25px;\">1. Thermal Equilibrium and Definition of Temperature & Zeroth Law of Thermodynamics</h2>\n  \n  \n  <div style=\"background: rgba(255, 81, 47, 0.06); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Zeroth Law of Thermodynamics):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">If two systems A and B are separately in thermal equilibrium with a third system C, then system A and system B are also in thermal equilibrium with each other.</p>\n  </div>\n\n  <p>Thermodynamics is the branch of physics dealing with heat, work, temperature, and their interconversions. The concept of thermal equilibrium forms the logical foundation of temperature measurement.</p>\n\n  <div style=\"margin: 12px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Diathermal Wall:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">A wall that permits energy flow in the form of heat between two systems.</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Adiabatic Wall:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">An insulating wall that strictly prevents heat transfer between two systems.</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Temperature Definition:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Temperature is a scalar thermodynamic state variable whose equality determines thermal equilibrium between systems.</span>\n  </div>\n  </div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #FF512F; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(255, 81, 47, 0.25);\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Zeroth Law of Thermodynamics & Thermal Equilibrium Model\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <linearGradient id=\"boxGrad1\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"rgba(255, 81, 47, 0.25)\"/>\n      <stop offset=\"100%\" stop-color=\"rgba(255, 81, 47, 0.05)\"/>\n    </linearGradient>\n  </defs>\n\n  <!-- Left Side: System Setup (Width 365, Center x = 182) -->\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Systems A, B &amp; C in Equilibrium</text>\n\n    <!-- System A -->\n    <rect x=\"40\" y=\"70\" width=\"120\" height=\"120\" rx=\"10\" fill=\"url(#boxGrad1)\" stroke=\"#FF512F\" stroke-width=\"2\"/>\n    <text x=\"100\" y=\"125\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">System A</text>\n    <text x=\"100\" y=\"150\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14\">Temp T_A</text>\n\n    <!-- System B -->\n    <rect x=\"205\" y=\"70\" width=\"120\" height=\"120\" rx=\"10\" fill=\"url(#boxGrad1)\" stroke=\"#FF512F\" stroke-width=\"2\"/>\n    <text x=\"265\" y=\"125\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">System B</text>\n    <text x=\"265\" y=\"150\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14\">Temp T_B</text>\n\n    <!-- Adiabatic Insulating Wall between A and B -->\n    <line x1=\"182\" y1=\"65\" x2=\"182\" y2=\"195\" stroke=\"#94A3B8\" stroke-width=\"8\" stroke-dasharray=\"4,4\"/>\n    <text x=\"182\" y=\"215\" text-anchor=\"middle\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"12.5\">Adiabatic Wall (No Heat)</text>\n\n    <!-- Diathermal Heat Wall between AB and C -->\n    <line x1=\"30\" y1=\"230\" x2=\"335\" y2=\"230\" stroke=\"#76FF03\" stroke-width=\"5\"/>\n    <text x=\"182\" y=\"250\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">Diathermal Wall (Conducts Heat)</text>\n\n    <!-- System C -->\n    <rect x=\"75\" y=\"265\" width=\"215\" height=\"100\" rx=\"10\" fill=\"url(#boxGrad1)\" stroke=\"#00E5FF\" stroke-width=\"2\"/>\n    <text x=\"182\" y=\"315\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">System C (Thermometer)</text>\n    <text x=\"182\" y=\"340\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14\">Temp T_C</text>\n  </g>\n\n  <!-- Vertical Divider -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"450\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Side: Zeroth Law Summary Card (Width 365, Center x = 182) -->\n  <g transform=\"translate(415, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"430\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#FF512F\" stroke-width=\"1.8\"/>\n    <text x=\"182\" y=\"35\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. Zeroth Law Statement &amp; Temp</text>\n\n    <rect x=\"10\" y=\"60\" width=\"345\" height=\"110\" rx=\"8\" fill=\"rgba(255,81,47,0.1)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"85\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Zeroth Law Statement:</text>\n    <text x=\"182\" y=\"118\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13.5\">If two systems A and B are separately in thermal equilibrium with a third system C, then A and B are also in thermal equilibrium with each other.</text>\n\n    <rect x=\"10\" y=\"185\" width=\"345\" height=\"100\" rx=\"8\" fill=\"rgba(0,229,255,0.1)\" stroke=\"#00E5FF\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"210\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Mathematical Condition:</text>\n    <text x=\"182\" y=\"245\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">If T_A = T_C &amp; T_B = T_C  ⇒  T_A = T_B</text>\n\n    <rect x=\"10\" y=\"300\" width=\"345\" height=\"115\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"325\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Concept of Temperature:</text>\n    <text x=\"182\" y=\"358\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13.5\">• Forms the basis for temperature measurement!</text>\n    <text x=\"182\" y=\"385\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"13\">• Temperature is a scalar state variable.</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 3 Systems A, B, and C with diathermal and adiabatic walls proving T_A = T_B = T_C.\n    </div>\n  </div>\n\n  <!-- SECTION 2: HEAT, WORK AND INTERNAL ENERGY (100% OFFICIAL SYLLABUS TITLE) -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">2. Heat, Work and Internal Energy</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.06); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Internal Energy (U)):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">The total energy possessed by a thermodynamic system due to molecular motion (kinetic energy) and intermolecular forces (potential energy). For an ideal gas, U is purely kinetic and depends solely on temperature T.</p>\n  </div>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>Work: W = ∫ P dV &nbsp;|&nbsp; Internal Energy: U = U(T) &nbsp;|&nbsp; Heat: Q = Transit Energy</b></div>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(i) Fundamental Thermodynamic Quantities</h3>\n  <div style=\"margin: 12px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Heat Q:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Energy transferred across system boundary due to temperature difference alone. Transient path function.</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Work W:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Energy transferred across system boundary by organized mechanical displacement. Path function W = ∫ P dV.</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Internal Energy U:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">State function depending solely on current state variables (P, V, T), independent of path taken.</span>\n  </div>\n  </div>\n\n  <!-- SECTION 3: FIRST LAW OF THERMODYNAMICS (100% OFFICIAL SYLLABUS TITLE) -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">3. First Law of Thermodynamics</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.06); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (First Law of Thermodynamics):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">A statement of law of conservation of energy applied to thermodynamic systems: The heat ΔQ absorbed by a system is spent in increasing internal energy ΔU and performing mechanical work ΔW.</p>\n  </div>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>ΔQ = ΔU + ΔW &nbsp; (or dQ = dU + P dV)</b></div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #FF512F; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(255, 81, 47, 0.25);\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 First Law of Thermodynamics & Gas Piston Cylinder System\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <linearGradient id=\"gasGrad2\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"rgba(255, 81, 47, 0.4)\"/>\n      <stop offset=\"100%\" stop-color=\"rgba(255, 215, 0, 0.15)\"/>\n    </linearGradient>\n    <marker id=\"arrowRed2\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#FF512F\"/>\n    </marker>\n    <marker id=\"arrowGreen2\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#76FF03\"/>\n    </marker>\n  </defs>\n\n  <!-- Left Side: Piston Cylinder Diagram (Width 365, Center x = 182) -->\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Gas Cylinder &amp; Piston Expansion</text>\n\n    <!-- Insulated Cylinder -->\n    <rect x=\"75\" y=\"80\" width=\"215\" height=\"250\" rx=\"10\" fill=\"none\" stroke=\"#475569\" stroke-width=\"4\"/>\n    <rect x=\"79\" y=\"160\" width=\"207\" height=\"166\" fill=\"url(#gasGrad2)\"/>\n\n    <!-- Piston moving up -->\n    <rect x=\"77\" y=\"145\" width=\"211\" height=\"22\" rx=\"4\" fill=\"#00E5FF\"/>\n    <line x1=\"182\" y1=\"145\" x2=\"182\" y2=\"70\" stroke=\"#76FF03\" stroke-width=\"4.5\" marker-end=\"url(#arrowGreen2)\"/>\n    <text x=\"182\" y=\"55\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Work Done ΔW = P ΔV</text>\n\n    <!-- Heat Input ΔQ from bottom -->\n    <line x1=\"182\" y1=\"380\" x2=\"182\" y2=\"335\" stroke=\"#FF512F\" stroke-width=\"4.5\" marker-end=\"url(#arrowRed2)\"/>\n    <text x=\"182\" y=\"405\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Heat Added ΔQ</text>\n\n    <!-- Gas Internal Energy ΔU -->\n    <text x=\"182\" y=\"240\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Ideal Gas (ΔU)</text>\n  </g>\n\n  <!-- Vertical Divider -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"450\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Side: First Law Equation & Sign Conventions Card (Width 365, Center x = 182) -->\n  <g transform=\"translate(415, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"430\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#FF512F\" stroke-width=\"1.8\"/>\n    <text x=\"182\" y=\"35\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. First Law of Thermodynamics</text>\n\n    <rect x=\"10\" y=\"60\" width=\"345\" height=\"90\" rx=\"8\" fill=\"rgba(255,81,47,0.1)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"85\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">First Law Equation (Conservation of Energy):</text>\n    <text x=\"182\" y=\"122\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"18\" font-weight=\"bold\">ΔQ = ΔU + ΔW</text>\n\n    <rect x=\"10\" y=\"165\" width=\"345\" height=\"120\" rx=\"8\" fill=\"rgba(0,229,255,0.1)\" stroke=\"#00E5FF\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"190\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Sign Conventions:</text>\n    <text x=\"25\" y=\"218\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13.5\">• ΔQ &gt; 0: Heat added to system</text>\n    <text x=\"25\" y=\"240\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13.5\">• ΔW &gt; 0: Work done BY system (Expansion)</text>\n    <text x=\"25\" y=\"262\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13.5\">• ΔU &gt; 0: Internal energy increases (Temp rises)</text>\n\n    <rect x=\"10\" y=\"295\" width=\"345\" height=\"115\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"320\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Internal Energy U (State Function):</text>\n    <text x=\"182\" y=\"352\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"16.5\" font-weight=\"bold\">U = U(T) &nbsp; (For Ideal Gas)</text>\n    <text x=\"182\" y=\"385\" text-anchor=\"middle\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">• Cyclic process: ∮ dU = 0  ⇒  Q_net = W_net</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 Piston cylinder expansion model showing heat addition ΔQ, internal energy change ΔU, and work done ΔW.\n    </div>\n  </div>\n\n  <!-- SECTION 4: CHANGE OF CONDITION OF GASEOUS STATE - ISOTHERMAL, ADIABATIC, REVERSIBLE, IRREVERSIBLE, AND CYCLIC PROCESSES (100% OFFICIAL SYLLABUS TITLE) -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">4. Change of Condition of Gaseous State - Isothermal, Adiabatic, Reversible, Irreversible, and Cyclic Processes</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.06); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Isothermal & Adiabatic Processes):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">Isothermal: ΔT = 0, PV = Const, W = 2.303 n R T log₁₀(V₂/V₁). Adiabatic: Q = 0, PV<sup>γ</sup> = Const, W = n R (T₁ - T₂) / (γ - 1).</p>\n  </div>\n\n  <div style=\"margin: 12px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• 1. Isothermal Process:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Occurs slowly in thin conducting vessel so temperature remains strictly constant (ΔT = 0, ΔU = 0). Equation: P V = Constant.</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• 2. Adiabatic Process:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Occurs suddenly/rapidly in insulated vessel with zero heat exchange (Q = 0). Equation: P V<sup>γ</sup> = Constant, where γ = C_p / C_v.</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #FF512F; font-size: 15.5px; display: block; margin-bottom: 3px;\">• 3. Cyclic Process:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">System returns to initial state. ΔU_cycle = 0, so Q_net = W_net = Area enclosed by P-V loop.</span>\n  </div>\n  </div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #FF512F; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(255, 81, 47, 0.25);\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Isothermal vs Adiabatic Expansion P-V Curve Comparison\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <!-- Left Side: P-V Curves (Width 365, Center x = 182) -->\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. P-V Curves: Isothermal vs Adiabatic</text>\n\n    <!-- Axes -->\n    <line x1=\"50\" y1=\"330\" x2=\"340\" y2=\"330\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <line x1=\"50\" y1=\"330\" x2=\"50\" y2=\"60\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <text x=\"345\" y=\"335\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">Volume V</text>\n    <text x=\"40\" y=\"50\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">Pressure P</text>\n\n    <!-- Common Initial State A (P1, V1) -->\n    <circle cx=\"90\" cy=\"100\" r=\"7\" fill=\"#FFD700\"/>\n    <text x=\"95\" y=\"90\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"13.5\" font-weight=\"bold\">A (P₁, V₁)</text>\n\n    <!-- Isothermal Expansion Curve (PV = Const) -->\n    <path d=\"M 90 100 Q 170 180 310 230\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"3.5\"/>\n    <text x=\"240\" y=\"200\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Isothermal (PV = C)</text>\n\n    <!-- Adiabatic Expansion Curve (PV<sup>γ</sup> = Const, Steeper) -->\n    <path d=\"M 90 100 Q 150 230 310 300\" fill=\"none\" stroke=\"#FF512F\" stroke-width=\"3.5\"/>\n    <text x=\"180\" y=\"280\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Adiabatic (PV<sup>γ</sup> = C)</text>\n\n    <text x=\"182\" y=\"380\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Adiabatic Slope = γ × Isothermal Slope!</text>\n  </g>\n\n  <!-- Vertical Divider -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"450\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Side: Process Work & Equations Card (Width 365, Center x = 182) -->\n  <g transform=\"translate(415, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"430\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#FF512F\" stroke-width=\"1.8\"/>\n    <text x=\"182\" y=\"35\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. Isothermal &amp; Adiabatic Formulae</text>\n\n    <rect x=\"10\" y=\"60\" width=\"345\" height=\"110\" rx=\"8\" fill=\"rgba(0,229,255,0.1)\" stroke=\"#00E5FF\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"85\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Isothermal Process (T = Const, ΔU = 0):</text>\n    <text x=\"182\" y=\"118\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"16\" font-weight=\"bold\">W_iso = 2.303 n R T log₁₀(V₂ / V₁)</text>\n    <text x=\"182\" y=\"148\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13\">✓ Q = W (Slow process in conducting vessel)</text>\n\n    <rect x=\"10\" y=\"185\" width=\"345\" height=\"120\" rx=\"8\" fill=\"rgba(255,81,47,0.1)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"210\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Adiabatic Process (Q = 0, PV<sup>γ</sup> = Const):</text>\n    <text x=\"182\" y=\"245\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"16\" font-weight=\"bold\">W_adia = n R (T₁ - T₂) / (γ - 1)</text>\n    <text x=\"182\" y=\"280\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"monospace\" font-size=\"13.5\">W_adia = (P₁ V₁ - P₂ V₂) / (γ - 1)</text>\n\n    <rect x=\"10\" y=\"315\" width=\"345\" height=\"100\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"340\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Slope Comparison:</text>\n    <text x=\"182\" y=\"372\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"16\" font-weight=\"bold\">(dP/dV)_adia = γ (dP/dV)_iso</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 P-V indicator diagram showing Isothermal curve (PV=C) alongside steeper Adiabatic curve (PV<sup>γ</sup>=C).\n    </div>\n  </div>\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #FF512F; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(255, 81, 47, 0.25);\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Cyclic Process P-V Loop & Enclosed Area Work Output\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <linearGradient id=\"loopGrad4\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"rgba(118, 255, 3, 0.35)\"/>\n      <stop offset=\"100%\" stop-color=\"rgba(118, 255, 3, 0.05)\"/>\n    </linearGradient>\n  </defs>\n\n  <!-- Left Side: P-V Loop (Width 365, Center x = 182) -->\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Clockwise Cyclic Process P-V Loop</text>\n\n    <!-- Axes -->\n    <line x1=\"50\" y1=\"330\" x2=\"340\" y2=\"330\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <line x1=\"50\" y1=\"330\" x2=\"50\" y2=\"60\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <text x=\"345\" y=\"335\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">Volume V</text>\n    <text x=\"40\" y=\"50\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">Pressure P</text>\n\n    <!-- Closed Elliptical Clockwise Cycle -->\n    <ellipse cx=\"190\" cy=\"190\" rx=\"90\" ry=\"60\" fill=\"url(#loopGrad4)\" stroke=\"#76FF03\" stroke-width=\"3.5\"/>\n\n    <!-- Arrows on Cycle -->\n    <path d=\"M 230 132 L 245 130 L 235 145\" fill=\"#76FF03\"/>\n    <path d=\"M 150 248 L 135 250 L 145 235\" fill=\"#76FF03\"/>\n\n    <text x=\"190\" y=\"195\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Enclosed Work Area W</text>\n    <text x=\"182\" y=\"380\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Clockwise Loop ⇒ Net Positive Work Output W &gt; 0</text>\n  </g>\n\n  <!-- Vertical Divider -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"450\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Side: Cyclic Process Properties Card (Width 365, Center x = 182) -->\n  <g transform=\"translate(415, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"430\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#FF512F\" stroke-width=\"1.8\"/>\n    <text x=\"182\" y=\"35\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. Cyclic Process Laws &amp; Reversibility</text>\n\n    <rect x=\"10\" y=\"60\" width=\"345\" height=\"90\" rx=\"8\" fill=\"rgba(255,81,47,0.1)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"85\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Internal Energy in Cyclic Process:</text>\n    <text x=\"182\" y=\"122\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"18\" font-weight=\"bold\">ΔU_cycle = 0 &nbsp; ⇒ &nbsp; Q_net = W_net</text>\n\n    <rect x=\"10\" y=\"165\" width=\"345\" height=\"110\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"190\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Work Done = Area Enclosed:</text>\n    <text x=\"182\" y=\"225\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">W = ∮ P dV = Area of P-V Loop</text>\n    <text x=\"182\" y=\"255\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"13\">✓ Clockwise: Heat Engine | Counter-Clockwise: Refrigerator</text>\n\n    <rect x=\"10\" y=\"290\" width=\"345\" height=\"120\" rx=\"8\" fill=\"rgba(0,229,255,0.1)\" stroke=\"#00E5FF\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"315\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Reversible vs Irreversible Process:</text>\n    <text x=\"25\" y=\"343\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13\">• Reversible: Quasi-static, zero dissipation, retraces path</text>\n    <text x=\"25\" y=\"365\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13\">• Irreversible: Spontaneous, friction/turbulence present</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 Clockwise P-V loop showing net positive work output W_net = ∮ P dV and state function ΔU_cycle = 0.\n    </div>\n  </div>\n\n  <!-- SECTION 5: SECOND LAW OF THERMODYNAMICS (100% OFFICIAL SYLLABUS TITLE) -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">5. Second Law of Thermodynamics</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.06); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Second Law of Thermodynamics):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">Establishes the directional constraints of natural heat flow. Kelvin-Planck: Impossible to convert heat completely into work. Clausius: Heat cannot flow spontaneously from cold to hot body.</p>\n  </div>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>Heat Engine Efficiency: η = 1 - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">T<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">T<sub>1</sub></span>\n  </span> &nbsp;|&nbsp; Refrigerator COP: β = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">T<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">T<sub>1</sub> - T<sub>2</sub></span>\n  </span></b></div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #FF512F; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(255, 81, 47, 0.25);\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Heat Engine & Carnot Engine Efficiency (Kelvin-Planck Statement)\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <marker id=\"arrowRed5\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#FF512F\"/>\n    </marker>\n    <marker id=\"arrowGreen5\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#76FF03\"/>\n    </marker>\n    <marker id=\"arrowCyan5\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#00E5FF\"/>\n    </marker>\n  </defs>\n\n  <!-- Left Side: Heat Engine Flow Chart (Width 365, Center x = 182) -->\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Heat Engine (Kelvin-Planck Law)</text>\n\n    <!-- Source Reservoir T1 -->\n    <rect x=\"80\" y=\"60\" width=\"204\" height=\"50\" rx=\"8\" fill=\"rgba(255,81,47,0.3)\" stroke=\"#FF512F\" stroke-width=\"2\"/>\n    <text x=\"182\" y=\"90\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Hot Source (Temp T₁)</text>\n\n    <!-- Engine Working Substance -->\n    <circle cx=\"182\" cy=\"200\" r=\"40\" fill=\"rgba(255,215,0,0.2)\" stroke=\"#FFD700\" stroke-width=\"2\"/>\n    <text x=\"182\" y=\"205\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Engine</text>\n\n    <!-- Q1 Arrow down -->\n    <line x1=\"182\" y1=\"110\" x2=\"182\" y2=\"160\" stroke=\"#FF512F\" stroke-width=\"4\" marker-end=\"url(#arrowRed5)\"/>\n    <text x=\"210\" y=\"140\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Q₁</text>\n\n    <!-- Work Output Arrow right -->\n    <line x1=\"222\" y1=\"200\" x2=\"310\" y2=\"200\" stroke=\"#76FF03\" stroke-width=\"4\" marker-end=\"url(#arrowGreen5)\"/>\n    <text x=\"260\" y=\"190\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Work W</text>\n\n    <!-- Q2 Arrow down to Sink -->\n    <line x1=\"182\" y1=\"240\" x2=\"182\" y2=\"290\" stroke=\"#00E5FF\" stroke-width=\"4\" marker-end=\"url(#arrowCyan5)\"/>\n    <text x=\"210\" y=\"270\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Q₂</text>\n\n    <!-- Sink Reservoir T2 -->\n    <rect x=\"80\" y=\"290\" width=\"204\" height=\"50\" rx=\"8\" fill=\"rgba(0,229,255,0.2)\" stroke=\"#00E5FF\" stroke-width=\"2\"/>\n    <text x=\"182\" y=\"320\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Cold Sink (Temp T₂)</text>\n\n    <text x=\"182\" y=\"380\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Efficiency η = W / Q₁ = 1 - (Q₂ / Q₁)</text>\n  </g>\n\n  <!-- Vertical Divider -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"450\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Side: Carnot Engine & Kelvin-Planck Statement Card (Width 365, Center x = 182) -->\n  <g transform=\"translate(415, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"430\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#FF512F\" stroke-width=\"1.8\"/>\n    <text x=\"182\" y=\"35\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. Carnot Engine Efficiency Laws</text>\n\n    <rect x=\"10\" y=\"60\" width=\"345\" height=\"110\" rx=\"8\" fill=\"rgba(255,81,47,0.1)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"85\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Kelvin-Planck Statement:</text>\n    <text x=\"182\" y=\"118\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13.5\">It is impossible to construct an engine operating in a cycle that absorbs heat from a reservoir and converts it entirely into work without rejecting heat to a cold sink.</text>\n\n    <rect x=\"10\" y=\"185\" width=\"345\" height=\"100\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"210\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Carnot Engine Efficiency η:</text>\n    <text x=\"182\" y=\"245\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"18\" font-weight=\"bold\">η = 1 - (T₂ / T₁)</text>\n\n    <rect x=\"10\" y=\"300\" width=\"345\" height=\"115\" rx=\"8\" fill=\"rgba(0,229,255,0.1)\" stroke=\"#00E5FF\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"325\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Carnot Cycle 4 Stages:</text>\n    <text x=\"25\" y=\"353\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13\">• 1. Isothermal Expansion (T₁) &nbsp;|&nbsp; 2. Adiabatic Expansion</text>\n    <text x=\"25\" y=\"375\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13\">• 3. Isothermal Compression (T₂) | 4. Adiabatic Compression</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 Thermal energy reservoir flow chart for heat engine working between T1 and T2 showing Carnot efficiency η = 1 - T2/T1.\n    </div>\n  </div>\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #FF512F; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(255, 81, 47, 0.25);\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Refrigerator & Heat Pump (Clausius Statement & COP β)\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <marker id=\"arrowRed6\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#FF512F\"/>\n    </marker>\n    <marker id=\"arrowGreen6\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#76FF03\"/>\n    </marker>\n    <marker id=\"arrowCyan6\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#00E5FF\"/>\n    </marker>\n  </defs>\n\n  <!-- Left Side: Refrigerator Flow Chart (Width 365, Center x = 182) -->\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Refrigerator (Clausius Statement)</text>\n\n    <!-- Hot Surroundings T1 -->\n    <rect x=\"80\" y=\"60\" width=\"204\" height=\"50\" rx=\"8\" fill=\"rgba(255,81,47,0.3)\" stroke=\"#FF512F\" stroke-width=\"2\"/>\n    <text x=\"182\" y=\"90\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Hot Room (Temp T₁)</text>\n\n    <!-- Compressor Working Substance -->\n    <circle cx=\"182\" cy=\"200\" r=\"40\" fill=\"rgba(0,229,255,0.2)\" stroke=\"#00E5FF\" stroke-width=\"2\"/>\n    <text x=\"182\" y=\"205\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Compressor</text>\n\n    <!-- Work Input Arrow in from left -->\n    <line x1=\"60\" y1=\"200\" x2=\"142\" y2=\"200\" stroke=\"#76FF03\" stroke-width=\"4\" marker-end=\"url(#arrowGreen6)\"/>\n    <text x=\"100\" y=\"190\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Work W</text>\n\n    <!-- Q1 Arrow up to Hot Surroundings -->\n    <line x1=\"182\" y1=\"160\" x2=\"182\" y2=\"110\" stroke=\"#FF512F\" stroke-width=\"4\" marker-end=\"url(#arrowRed6)\"/>\n    <text x=\"210\" y=\"140\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Q₁ = Q₂ + W</text>\n\n    <!-- Q2 Arrow up from Cold Reservoir -->\n    <line x1=\"182\" y1=\"290\" x2=\"182\" y2=\"240\" stroke=\"#00E5FF\" stroke-width=\"4\" marker-end=\"url(#arrowCyan6)\"/>\n    <text x=\"210\" y=\"270\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Q₂</text>\n\n    <!-- Cold Chamber T2 -->\n    <rect x=\"80\" y=\"290\" width=\"204\" height=\"50\" rx=\"8\" fill=\"rgba(0,229,255,0.2)\" stroke=\"#00E5FF\" stroke-width=\"2\"/>\n    <text x=\"182\" y=\"320\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Cold Chamber (Temp T₂)</text>\n\n    <text x=\"182\" y=\"380\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">COP β = Q₂ / W = T₂ / (T₁ - T₂)</text>\n  </g>\n\n  <!-- Vertical Divider -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"450\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Side: Clausius Statement & COP Formulae Card (Width 365, Center x = 182) -->\n  <g transform=\"translate(415, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"430\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#FF512F\" stroke-width=\"1.8\"/>\n    <text x=\"182\" y=\"35\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. Clausius Statement &amp; COP β</text>\n\n    <rect x=\"10\" y=\"60\" width=\"345\" height=\"110\" rx=\"8\" fill=\"rgba(255,81,47,0.1)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"85\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Clausius Statement:</text>\n    <text x=\"182\" y=\"118\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13.5\">It is impossible for a self-acting machine, unaided by external agency, to transfer heat from a body at lower temperature to a body at higher temperature.</text>\n\n    <rect x=\"10\" y=\"185\" width=\"345\" height=\"100\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"210\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Coefficient of Performance (COP β):</text>\n    <text x=\"182\" y=\"245\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">β = Q₂ / W = T₂ / (T₁ - T₂)</text>\n\n    <rect x=\"10\" y=\"300\" width=\"345\" height=\"115\" rx=\"8\" fill=\"rgba(0,229,255,0.1)\" stroke=\"#00E5FF\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"325\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Relation between Efficiency η &amp; COP β:</text>\n    <text x=\"182\" y=\"360\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">β = (1 - η) / η</text>\n    <text x=\"182\" y=\"390\" text-anchor=\"middle\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">• Ideal Carnot Refrigerator can have β &gt; 1!</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 Heat pump compressor model extracting heat Q2 from cold chamber rejecting Q1 to hot room with COP β.\n    </div>\n  </div>\n\n  <!-- QUICK REVISION CHEAT SHEET -->\n  <div style=\"background: rgba(255, 81, 47, 0.05); border: 1.5px solid #FF512F; border-radius: 12px; padding: 16px; margin-top: 35px; margin-bottom: 15px;\">\n    <h2 class=\"text-center\" style=\"color: #FF512F; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">⚡ Quick Revision Cheat Sheet</h2>\n    <p class=\"text-center\" style=\"color: #FF512F; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Key Formulae, First & Second Laws, Carnot Engine Summary for Unit VIII</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 10px; font-size: 14px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>• First Law Equation:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">ΔQ = ΔU + ΔW<br>W = ∫ P dV</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>• Isothermal Work:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">PV = Const &nbsp;|&nbsp; ΔU = 0<br>W = 2.303 n R T log<sub>10</sub>(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">V<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">V<sub>1</sub></span>\n  </span>)</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>• Adiabatic Work:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">PV<sup>γ</sup> = Const &nbsp;|&nbsp; Q = 0<br>W = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">n R (T<sub>1</sub> - T<sub>2</sub>)</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">γ - 1</span>\n  </span></span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>• Cyclic Process Work:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">ΔU<sub>cycle</sub> = 0 &nbsp;|&nbsp; Q<sub>net</sub> = W<sub>net</sub><br>W = Area of P-V Loop</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>• Carnot Engine Efficiency:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">η = 1 - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">T<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">T<sub>1</sub></span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">W</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">Q<sub>1</sub></span>\n  </span></span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 3px;'>• Refrigerator COP:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">β = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Q<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">W</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">T<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">T<sub>1</sub> - T<sub>2</sub></span>\n  </span><br>β = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1 - η</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">η</span>\n  </span></span>\n      </div>\n    </div>\n  </div>\n\n</div>\n";

export const c11Phy8HtmlSolutions = "<style>\n    p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) { text-align: justify !important; }\n    h1, h2, h3, h4, h5, h6 { text-align: left; }\n    .text-center { text-align: center !important; }\n  </style>\n  <div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.7; font-size: 16px;\">\n  <h1 style=\"color: #FF512F; border-bottom: 2.5px solid #FF512F; padding-bottom: 6px; margin-top: 10px;\">NCERT & Textbook Standard Exercise Solutions — Unit VIII: Thermodynamics</h1><h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 25px;\">SECTION 1: MULTIPLE CHOICE QUESTIONS (MCQs 1 - 25)</h2>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q1: Zeroth law of thermodynamics forms the basis for the measurement of:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) Pressure</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Work</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Heat</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) Temperature</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (d)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Zeroth law defines temperature as the scalar state variable determining thermal equilibrium.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q2: First law of thermodynamics is a restatement of law of conservation of:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) Charge</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Energy</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Momentum</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) Mass</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> First law ΔQ = ΔU + ΔW expresses conservation of thermodynamic energy.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q3: In an isothermal expansion of an ideal gas, internal energy change ΔU is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) Positive</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Negative</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Zero</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) Infinite</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (c)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> For ideal gas U depends solely on T. In isothermal process ΔT = 0, so ΔU = 0.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q4: During an adiabatic process, heat exchange ΔQ between system and surroundings is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) Positive</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Negative</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Zero</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) Variable</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (c)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> An adiabatic process occurs in an insulated vessel with zero heat transfer (ΔQ = 0).</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q5: The work done in an isochoric process is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) P ΔV</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Zero</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) n R T</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) ΔU</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> In an isochoric process volume remains constant (ΔV = 0), so W = ∫ P dV = 0.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q6: Slope of an adiabatic curve on a P-V diagram compared to an isothermal curve is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) Equal</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Less steep</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) γ times steeper</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 1/γ times steeper</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (c)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> (dP/dV)_adia = -γ (P/V) = γ × (dP/dV)_iso. Adiabatic slope is γ times steeper.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q7: In a cyclic process, the net work done by the system is equal to:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) Zero</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Area enclosed by P-V loop</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Change in internal energy</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) Total initial heat</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Since ΔU_cycle = 0, W_net = Q_net = Area enclosed inside closed P-V loop.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q8: The efficiency η of a Carnot engine working between source T₁ and sink T₂ is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 1 - T₁/T₂</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 1 - T₂/T₁</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) T₂/T₁</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) T₁/T₂ - 1</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Carnot efficiency η = 1 - T₂/T₁ where temperatures are in Kelvin.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q9: Kelvin-Planck statement of Second Law deals with:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) Heat engines</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Refrigerators</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Thermometers</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) Calorimeters</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (a)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Kelvin-Planck statement rules out 100% efficient heat engines converting heat completely to work.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q10: Clausius statement of Second Law deals with:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) Heat engines</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Refrigerators / Heat pumps</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Ideal gases</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) Internal energy</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Clausius statement states heat cannot flow spontaneously from cold to hot reservoir without work.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q11: The relation between efficiency η of a heat engine and COP β of a Carnot refrigerator is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) β = 1 / η</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) β = (1 - η) / η</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) β = η / (1 - η)</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) β = 1 + η</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> β = Q₂/W = T₂/(T₁ - T₂) = (1 - η)/η.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q12: For a monoatomic gas (γ = 5/3), if volume is compressed adiabatically to 1/8th of its initial volume, pressure increases by a factor of:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 8</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 16</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 32</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 64</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (c)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> P₂/P₁ = (V₁/V₂)<sup>γ</sup> = (8)<sup>5/3</sup> = (2<sup>3</sup>)<sup>5/3</sup> = 2<sup>5</sup> = 32.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q13: In an adiabatic expansion, the temperature of an ideal gas:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) Increases</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Decreases</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Remains constant</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) First increases then decreases</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> W = -ΔU > 0 ⇒ ΔU < 0. Internal energy drops, causing gas temperature to fall.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q14: Which of the following is NOT a state function?</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) Pressure</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Volume</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Internal Energy</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) Work</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (d)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Work W and Heat Q are path functions, while P, V, T, U are state functions.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q15: The area of P-V diagram for a thermodynamic process represents:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) Heat absorbed</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Work done</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Temperature change</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) Internal energy</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Area under P-V curve ∫ P dV represents work done.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q16: An ideal gas undergoes isothermal expansion at 300 K absorbing 500 J heat. Work done by gas is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 0 J</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 250 J</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 500 J</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) -500 J</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (c)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> For isothermal process ΔU = 0, so W = Q = +500 J.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q17: Can a heat engine have 100% efficiency?</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) Yes, if sink is at 0 K</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Yes, if source is at 0 K</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Yes, if friction is zero</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) Never possible</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (a)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> η = 1 - T₂/T₁ = 100% only if T₂ = 0 K (Absolute Zero), which is practically unattainable by 3rd Law.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q18: A process in which no heat enters or leaves the system is called:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) Isothermal</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Isobaric</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Isochoric</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) Adiabatic</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (d)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Adiabatic process is characterized by Q = 0.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q19: A process in which pressure remains constant is called:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) Isobaric</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Isochoric</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Isothermal</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) Adiabatic</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (a)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Isobaric means constant pressure (ΔP = 0).</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q20: The ratio of molar heat capacities γ = C_p / C_v for a diatomic gas like O₂ is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 1.67</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 1.40</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 1.33</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 1.25</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> For a rigid diatomic gas, C_v = 5/2 R, C_p = 7/2 R, so γ = 7/5 = 1.40.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q21: A Carnot engine operates between 500 K and 300 K. Its efficiency is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 20%</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 40%</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 60%</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 80%</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> η = 1 - 300/500 = 1 - 0.6 = 0.4 = 40%.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q22: The COP of a refrigerator is 5. If it extracts 200 J heat from cold reservoir, work done by compressor is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 40 J</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 1000 J</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 50 J</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 200 J</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (a)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> β = Q₂ / W ⇒ W = Q₂ / β = 200 / 5 = 40 J.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q23: Quasi-static process is an ideal process which is extremely:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) Fast</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Slow</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Irreversible</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) Explosive</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Quasi-static process proceeds infinitely slowly through equilibrium states.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q24: If heat added to a system is 300 J and work done by system is 100 J, increase in internal energy is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 400 J</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 200 J</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 100 J</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) -200 J</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> ΔU = ΔQ - ΔW = 300 - 100 = 200 J.</div>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q25: A refrigerator door is left open in a closed room. The room temperature will:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) Decrease</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Increase</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Remain unchanged</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) Drop to 0°C</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #FF512F; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Refrigerator releases more heat to room Q₁ = Q₂ + W than it extracts Q₂, so room heats up.</div>\n    </div><h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">SECTION 2: VERY SHORT ANSWER QUESTIONS (VSAs 26 - 55)</h2>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q26: State the Zeroth Law of Thermodynamics.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> If systems A and B are separately in thermal equilibrium with C, then A and B are in thermal equilibrium with each other.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q27: What physical concept is defined by the Zeroth Law of Thermodynamics?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> Temperature.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q28: State the First Law of Thermodynamics.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> Conservation of energy statement: Heat added ΔQ = ΔU + ΔW.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q29: Distinguish between state functions and path functions.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> State functions (P, V, T, U) depend only on current equilibrium state; Path functions (Q, W) depend on path taken.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q30: What is an isothermal process?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> A thermodynamic process occurring at constant temperature (ΔT = 0, ΔU = 0).</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q31: What is an adiabatic process?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> A process in which no heat enters or leaves the system (Q = 0).</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q32: Write the equation of state for an adiabatic process in terms of P and V.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> P V<sup>γ</sup> = Constant.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q33: Write the formula for work done during an isothermal expansion.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> W = 2.303 n R T log₁₀(V₂ / V₁).</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q34: Write the formula for work done during an adiabatic expansion.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> W = n R (T₁ - T₂) / (γ - 1) = (P₁ V₁ - P₂ V₂) / (γ - 1).</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q35: Why is the adiabatic curve steeper than the isothermal curve on a P-V diagram?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> Because adiabatic slope (dP/dV)_adia = -γ (P/V) is γ times the isothermal slope -P/V.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q36: What is a cyclic process?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> A process in which the system returns to its initial thermodynamic state (ΔU_cycle = 0).</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q37: What is the net work done in a cyclic process equal to?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> The area enclosed by the closed loop on the P-V indicator diagram.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q38: State Kelvin-Planck statement of Second Law of Thermodynamics.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> Impossible to construct an engine operating in a cycle that absorbs heat from a reservoir and converts it completely to work without rejecting heat to cold sink.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q39: State Clausius statement of Second Law of Thermodynamics.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> Impossible for a self-acting device to transfer heat from a colder body to a hotter body without external work input.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q40: Write the formula for Carnot engine efficiency η in terms of temperatures T₁ and T₂.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> η = 1 - T₂ / T₁ (where T₁ is source temp and T₂ is sink temp in Kelvin).</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q41: What is a Carnot Refrigerator?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> A Carnot heat engine operating in reverse, extracting heat from a cold reservoir by consuming external work.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q42: Define Coefficient of Performance (COP) β of a refrigerator.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> β = Q₂ / W = T₂ / (T₁ - T₂).</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q43: Can a Carnot engine have 100% efficiency? Explain.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> No, because 100% efficiency requires sink temperature T₂ = 0 K, which is absolute zero and physically unattainable.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q44: What is a quasi-static process?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> An infinitely slow process passing through a continuous series of equilibrium states.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q45: Give two examples of irreversible processes.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> 1. Heat conduction through a temperature gradient. 2. Free expansion of a gas into vacuum.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q46: What is an isochoric process?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> A process occurring at constant volume (ΔV = 0, W = 0).</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q47: What is an isobaric process?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> A process occurring at constant pressure (ΔP = 0, W = P ΔV).</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q48: Why does air temperature fall when a bicycle tire bursts suddenly?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> Sudden expansion is adiabatic (Q = 0). Gas does work at expense of its internal energy (W = -ΔU), causing temperature drop.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q49: Why is an isothermal process carried out slowly in a thin metal container?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> To allow sufficient time for heat exchange through thin conducting walls to maintain constant temperature.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q50: What is the change in internal energy during one full cycle of a Carnot engine?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> Zero (ΔU_cycle = 0).</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q51: What is the ratio of slopes of adiabatic to isothermal curves for a gas with γ = 1.4?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> Ratio of slopes = γ = 1.4.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q52: Is work done in expanding a gas from V₁ to V₂ greater in isothermal or adiabatic process?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> Greater in isothermal process, because P-V curve for isothermal lies above adiabatic curve.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q53: What happens to entropy of universe in an irreversible process?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> Entropy of the universe always increases in an irreversible process.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q54: Can heat be completely converted into work in a single non-cyclic process?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> Yes, in an isothermal expansion Q = W, but this cannot be repeated continuously in a cycle.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q55: Why does a heat engine require two thermal reservoirs?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> To establish a temperature difference T₁ > T₂ allowing continuous heat absorption Q₁ and rejection Q₂.</p>\n    </div><h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">SECTION 3: SHORT ANSWER QUESTIONS (SAs 56 - 85)</h2>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q56: State Zeroth Law of Thermodynamics and explain how it leads to the definition of temperature.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Zeroth law states if A and B are in thermal equilibrium with C, then A and B are in equilibrium with each other. This defines a common scalar property T such that T_A = T_B = T_C.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q57: Explain the First Law of Thermodynamics and apply it to: (i) Isochoric process, (ii) Isothermal process.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> First Law: ΔQ = ΔU + ΔW.\n1. Isochoric (ΔV = 0 ⇒ W = 0): ΔQ = ΔU (Heat added increases internal energy).\n2. Isothermal (ΔT = 0 ⇒ ΔU = 0): ΔQ = ΔW (Heat added converts completely to work).</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q58: Derive an expression for work done during an isothermal expansion of n moles of ideal gas from V₁ to V₂.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> W = ∫[V₁ to V₂] P dV = ∫ n R T / V dV = n R T [ln V]_[V₁ to V₂] = n R T ln(V₂/V₁) = 2.303 n R T log₁₀(V₂/V₁).</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q59: Derive an expression for work done during an adiabatic expansion of n moles of ideal gas from T₁ to T₂.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> P V<sup>γ</sup> = K ⇒ W = ∫ P dV = K ∫ V<sup>-γ</sup> dV = [K / (1-γ)] [V<sub>2</sub><sup>1-γ</sup> - V<sub>1</sub><sup>1-γ</sup>] = (P₂ V₂ - P₁ V₁) / (1-γ) = n R (T₁ - T₂) / (γ - 1).</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q60: Show that slope of an adiabatic P-V curve is γ times the slope of an isothermal P-V curve.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> 1. Isothermal PV = C ⇒ P dV + V dP = 0 ⇒ (dP/dV)_iso = -P/V.\n2. Adiabatic PV<sup>γ</sup> = C ⇒ P γ V<sup>γ-1</sup> dV + V<sup>γ</sup> dP = 0 ⇒ (dP/dV)_adia = -γ (P/V) = γ (dP/dV)_iso.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q61: Differentiate between Reversible and Irreversible processes with two examples of each.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> 1. Reversible: Quasi-static, zero dissipation, retraces path (e.g. slow isothermal expansion, Carnot cycle).\n2. Irreversible: Spontaneous, dissipation present (e.g. free expansion, heat conduction).</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q62: State Kelvin-Planck and Clausius statements of Second Law of Thermodynamics and show their equivalence.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> 1. Kelvin-Planck: Impossible to build 100% efficient heat engine.\n2. Clausius: Heat cannot flow spontaneously from cold to hot body.\n3. Equivalence: Violation of Kelvin-Planck leads to violation of Clausius and vice-versa.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q63: Describe the 4 processes constituting a Carnot Cycle with P-V diagram.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> 1. Isothermal Expansion A→B at T₁ (absorbs Q₁).\n2. Adiabatic Expansion B→C (temp drops T₁ to T₂).\n3. Isothermal Compression C→D at T₂ (rejects Q₂).\n4. Adiabatic Compression D→A (temp rises T₂ to T₁).</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q64: Derive an expression for efficiency of a Carnot Engine operating between T₁ and T₂.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> η = W / Q₁ = (Q₁ - Q₂) / Q₁ = 1 - Q₂ / Q₁. For Carnot cycle Q₂ / Q₁ = T₂ / T₁, so efficiency η = 1 - T₂ / T₁.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q65: Explain the working of a Refrigerator and derive expression for its Coefficient of Performance (COP β).</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Working substance extracts Q₂ from cold chamber using compressor work W and rejects Q₁ = Q₂ + W to room. COP β = Q₂ / W = Q₂ / (Q₁ - Q₂) = T₂ / (T₁ - T₂).</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q66: A gas expands from 1 L to 4 L at constant pressure of 2 × 10⁵ Pa. Find work done by gas.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> W = P ΔV = 2 × 10⁵ Pa × (4 - 1) × 10⁻³ m³ = 2 × 10⁵ × 3 × 10⁻³ = 600 Joules.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q67: An ideal gas absorbs 1000 J heat and performs 400 J work. Find change in internal energy.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> ΔU = ΔQ - ΔW = 1000 - 400 = +600 Joules.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q68: 2 moles of ideal gas expand isothermally at 300 K from 2 L to 20 L. Calculate work done (R = 8.314 J/mol K).</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> W = 2.303 n R T log₁₀(V₂/V₁) = 2.303 × 2 × 8.314 × 300 × log₁₀(10) = 2.303 × 4988.4 × 1 = 11,488 Joules ≈ 11.49 kJ.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q69: A monoatomic gas (γ = 5/3) at 27°C is compressed adiabatically to 1/8th of its initial volume. Find final temperature.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> T₂ / T₁ = (V₁ / V₂)<sup>γ-1</sup> = (8)<sup>5/3 - 1</sup> = (8)<sup>2/3</sup> = (2<sup>3</sup>)<sup>2/3</sup> = 4. T₂ = 4 T₁ = 4 × (27 + 273) = 4 × 300 = 1200 K = 927°C.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q70: A Carnot engine operates between 600 K and 300 K. It absorbs 1200 J heat from source. Find work done and heat rejected.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Efficiency η = 1 - 300/600 = 0.5 (50%). Work W = η Q₁ = 0.5 × 1200 = 600 J. Heat rejected Q₂ = Q₁ - W = 1200 - 600 = 600 J.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q71: A Carnot refrigerator operates between 0°C and 30°C. Calculate its COP.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> T₂ = 0 + 273 = 273 K, T₁ = 30 + 273 = 303 K. COP β = T₂ / (T₁ - T₂) = 273 / (303 - 273) = 273 / 30 = 9.1.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q72: Explain why internal energy of an ideal gas depends ONLY on temperature.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> In an ideal gas, intermolecular potential energy is zero. Total internal energy U is purely kinetic energy of molecules, which is proportional to absolute temperature T.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q73: Why is C_p always greater than C_v for a gas?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> At constant volume, heat Q_v increases internal energy ΔU only. At constant pressure, heat Q_p increases ΔU AND performs expansion work P ΔV. Thus C_p > C_v.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q74: Distinguish between diathermal and adiabatic walls with examples.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> 1. Diathermal wall allows heat exchange (e.g. thin copper plate).\n2. Adiabatic wall prevents heat exchange (e.g. thick thermos flask wall, styrofoam).</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q75: Can internal energy of a system be increased without supplying heat? Explain.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Yes, by performing adiabatic work ON the system (W < 0). By First Law ΔQ = 0 ⇒ ΔU = -ΔW > 0 (e.g. compressing gas in insulated cylinder).</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q76: Draw P-V diagram for a cyclic process and show that net work done equals enclosed area.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Clockwise loop A→B (expansion work W_AB = area under top curve) and B→A (compression work W_BA = area under bottom curve). Net W = W_AB - W_BA = enclosed loop area.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q77: Explain why speed of sound in gas is an adiabatic process while Boyle's law experiment is isothermal.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> 1. Sound compressions/rarefactions occur extremely rapidly (no time for heat exchange ⇒ adiabatic).\n2. Boyle's law compression is performed very slowly allowing heat exchange with room (⇒ isothermal).</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q78: A Carnot engine has efficiency 40% when sink is at 300 K. To increase efficiency to 50%, find new source temp.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Initial: 0.40 = 1 - 300/T₁ ⇒ 300/T₁ = 0.60 ⇒ T₁ = 500 K. New: 0.50 = 1 - 300/T₁' ⇒ 300/T₁' = 0.50 ⇒ T₁' = 600 K. Source temp must be raised to 600 K.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q79: Calculate the change in internal energy when 2 moles of gas is heated at constant volume from 20°C to 100°C (C_v = 5 cal/mol K).</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Isochoric process W = 0 ⇒ ΔU = ΔQ = n C_v ΔT = 2 × 5 × (100 - 20) = 2 × 5 × 80 = 800 calories = 800 × 4.184 = 3347 J.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q80: If a heat engine rejects 3/4th of heat absorbed from source, what is its efficiency?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Q₂ = (3/4) Q₁ ⇒ Efficiency η = 1 - Q₂/Q₁ = 1 - 3/4 = 1/4 = 25%.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q81: Why is a heat pump more economical than an electric resistance heater for warming a room?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Electric heater delivers heat Q = W (COP = 1). Heat pump delivers Q₁ = W (1 + β) where β > 1, providing several times more heat per Joule of electricity.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q82: What is free expansion? Is it reversible or irreversible? Calculate work done.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Free expansion is unresisted expansion of gas into vacuum (P_ext = 0). W = 0, Q = 0, ΔU = 0. It is highly irreversible.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q83: A gas is compressed at constant pressure of 50 N/m² from 10 m³ to 4 m³. 100 J heat is added. Find ΔU.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> W = P ΔV = 50 × (4 - 10) = -300 J. By First Law ΔU = ΔQ - ΔW = +100 - (-300) = +400 Joules.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q84: Explain the physical significance of adiabatic index γ = C_p / C_v.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> γ represents the ratio of molar heat capacities, reflecting atomicity of gas molecules (Monoatomic γ=1.67, Diatomic γ=1.40, Triatomic γ=1.33).</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #FF512F; font-size: 15.5px;\">Q85: State two limitations of First Law of Thermodynamics.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> 1. Fails to specify direction of heat flow (does not explain why heat flows hot to cold).\n2. Does not specify feasibility or efficiency limit of converting heat into work.</p>\n    </div><h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">SECTION 4: LONG ANSWER QUESTIONS (LAs 86 - 100)</h2>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q86: State and explain First Law of Thermodynamics with sign conventions. Apply First Law to derive work and heat equations for: (i) Isothermal, (ii) Adiabatic, (iii) Isochoric, (iv) Isobaric processes.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Statement ΔQ = ΔU + ΔW.\n2. Isothermal: ΔT=0 ⇒ ΔU=0 ⇒ Q = W = 2.303 nRT log₁₀(V₂/V₁).\n3. Adiabatic: Q=0 ⇒ W = -ΔU = nR(T₁-T₂)/(γ-1).\n4. Isochoric: ΔV=0 ⇒ W=0 ⇒ Q = ΔU = n C_v ΔT.\n5. Isobaric: W = P ΔV ⇒ Q = n C_p ΔT.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q87: Derive an expression for work done in an Isothermal expansion and an Adiabatic expansion of an ideal gas. Compare the slopes of Isothermal and Adiabatic P-V curves.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. W_iso = 2.303 n R T log₁₀(V₂/V₁).\n2. W_adia = (P₁ V₁ - P₂ V₂) / (γ - 1).\n3. Slope derivation: Isothermal dP/dV = -P/V, Adiabatic dP/dV = -γ (P/V). Adiabatic slope is γ times steeper.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q88: What is a Carnot Heat Engine? Describe the 4 stages of Carnot cycle with P-V diagram. Derive an expression for its efficiency η in terms of temperatures T₁ and T₂.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Carnot Engine: Ideal reversible engine operating between T₁ and T₂.\n2. 4 Stages: (i) Isothermal Expansion A→B, (ii) Adiabatic Expansion B→C, (iii) Isothermal Compression C→D, (iv) Adiabatic Compression D→A.\n3. Efficiency: η = W / Q₁ = 1 - Q₂/Q₁ = 1 - T₂/T₁.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q89: State Second Law of Thermodynamics (Kelvin-Planck and Clausius statements). Prove their logical equivalence with neat flow diagrams.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Kelvin-Planck: Cannot build 100% efficient heat engine.\n2. Clausius: Heat cannot flow spontaneously from cold to hot body.\n3. Proof of equivalence: Show that a machine violating Kelvin-Planck statement coupled with a refrigerator violates Clausius statement.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q90: What is a Refrigerator? Explain its principle, working, and Coefficient of Performance (COP β). Derive relation between Carnot efficiency η and COP β.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Principle & Working: Reverse heat engine extracting Q₂ from cold chamber using work W and rejecting Q₁ to hot room.\n2. COP β = Q₂ / W = T₂ / (T₁ - T₂).\n3. Relation: β = (1 - η) / η.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q91: 1 mole of ideal monoatomic gas (γ = 5/3) initially at P₁ = 1 atm, V₁ = 24.6 L, T₁ = 300 K undergoes: (i) Isothermal expansion to 2 V₁, (ii) Adiabatic expansion to 4 V₁. Calculate final pressure, temperature, and total work done.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Isothermal to 2V₁: P_B = P₁/2 = 0.5 atm, T_B = 300 K. W_AB = nRT ln(2) = 1 × 8.314 × 300 × 0.693 = 1729 J.\n2. Adiabatic to 4V₁: P_C = P_B (V_B/V_C)<sup>γ</sup> = 0.5 (2V₁/4V₁)<sup>5/3</sup> = 0.5 (1/2)<sup>5/3</sup> = 0.157 atm. T_C = T_B (1/2)<sup>2/3</sup> = 300 × 0.630 = 189 K.\n3. W_BC = nR(T_B - T_C)/(γ-1) = 1 × 8.314 × (300 - 189) / (2/3) = 1.5 × 8.314 × 111 = 1384 J.\n4. Total Work W = 1729 + 1384 = 3113 Joules.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q92: A Carnot engine operates between 800 K and 400 K. In each cycle it absorbs 2000 J heat from source. Calculate: (i) Efficiency η, (ii) Work output W, (iii) Heat rejected Q₂, (iv) COP if operated as refrigerator between same temps.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. η = 1 - 400/800 = 0.50 (50%).\n2. W = η Q₁ = 0.50 × 2000 = 1000 Joules.\n3. Q₂ = Q₁ - W = 2000 - 1000 = 1000 Joules.\n4. Refrigerator COP β = T₂ / (T₁ - T₂) = 400 / (800 - 400) = 400 / 400 = 1.0.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q93: Differentiate between Reversible and Irreversible processes. State 4 essential conditions for a process to be strictly reversible.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Differences: Reversible proceeds via equilibrium states with zero dissipation; Irreversible has friction/turbulence.\n2. 4 Conditions: (i) Quasi-static extremely slow speed, (ii) Absence of friction and resistive forces, (iii) Zero temp difference across boundaries, (iv) Absence of hysteresis.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q94: A cyclic heat engine operates on a rectangular P-V diagram between P₁ = 1 × 10⁵ Pa, P₂ = 4 × 10⁵ Pa and V₁ = 2 m³, V₂ = 5 m³. Calculate net work done and heat transferred in one cycle.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Rectangular cycle P-V loop width ΔV = 5 - 2 = 3 m³, height ΔP = 4×10⁵ - 1×10⁵ = 3×10⁵ Pa.\n2. Net Work W = Area = ΔP × ΔV = (3 × 10⁵ Pa) × (3 m³) = 9.0 × 10⁵ Joules = 900 kJ.\n3. Since ΔU_cycle = 0, Net Heat Absorbed Q_net = W_net = 900 kJ.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q95: Explain the concept of Internal Energy U. Prove that internal energy is a state function while heat Q and work W are path functions.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Definition of U.\n2. Proof of U as state function: For any closed cycle ∮ dU = ∮ (dQ - dW) = 0, showing ΔU depends only on initial and final states.\n3. Heat and Work path dependence: Areas under different expansion curves between same initial and final volumes yield different W and Q values.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q96: Explain why efficiency of a Carnot engine depends ONLY on temperatures of source and sink, and NOT on the nature of working substance.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\nIn Carnot cycle, all heat absorption and rejection occur isothermally at T₁ and T₂, and adiabatic transitions connect them. Integrating dQ/T = 0 around reversible cycle yields Q₁/T₁ = Q₂/T₂ ⇒ η = 1 - T₂/T₁, completely independent of gas properties.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q97: A refrigerator extracts heat from water at 0°C to convert 2 kg water into ice at 0°C, rejecting heat to room at 27°C. Calculate minimum work required (L_f = 3.36 × 10⁵ J/kg).</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Heat extracted Q₂ = m L_f = 2 kg × 3.36 × 10⁵ J/kg = 6.72 × 10⁵ Joules.\n2. T₂ = 273 K, T₁ = 27 + 273 = 300 K.\n3. Max COP β = T₂ / (T₁ - T₂) = 273 / 27 = 9.1.\n4. Work W = Q₂ / β = 6.72 × 10⁵ / 9.1 = 7.38 × 10⁴ Joules = 73.8 kJ.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q98: Discuss the work done in Isochoric, Isobaric, Isothermal, and Adiabatic processes with P-V diagrams for each.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Isochoric (V=Const): W = 0 (Vertical line on P-V diagram).\n2. Isobaric (P=Const): W = P (V₂ - V₁) (Horizontal line).\n3. Isothermal (T=Const): W = 2.303 n R T log₁₀(V₂/V₁) (Hyperbolic curve PV=C).\n4. Adiabatic (Q=0): W = n R (T₁ - T₂)/(γ - 1) (Steeper curve PV<sup>γ</sup>=C).</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q99: Two Carnot engines A and B operate in series. Engine A receives heat at 900 K and rejects to intermediate temp T. Engine B receives heat rejected by A and rejects to sink at 400 K. Find T if: (i) Work outputs are equal (W_A = W_B), (ii) Efficiencies are equal (η_A = η_B).</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Equal Work (W_A = W_B ⇒ Q₁ - Q_mid = Q_mid - Q₂ ⇒ T₁ - T = T - T₂): T = (T₁ + T₂) / 2 = (900 + 400) / 2 = 650 K.\n2. Equal Efficiency (1 - T/T₁ = 1 - T₂/T ⇒ T/T₁ = T₂/T ⇒ T² = T₁ T₂): T = √(900 × 400) = √360000 = 600 K.</p>\n    </div>\n    <div style=\"background: rgba(255, 81, 47, 0.04); border-left: 4px solid #FF512F; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #FF512F; font-size: 16px;\">Q100: State and prove Carnot's Theorem. Explain why no real engine can have efficiency greater than a Carnot engine operating between same two temperatures.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Statement: No engine operating between two given temperatures can be more efficient than a reversible Carnot engine operating between same temperatures.\n2. Proof: Assume an irreversible engine I with η_I > η_R. Coupling I to reversed Carnot engine R produces a self-acting machine transferring heat from cold to hot reservoir without work, violating Clausius statement. Thus η_I ≤ η_R.</p>\n    </div></div>";
